// SigDump-Native - crash dump capture demo
function risky(n) { if (n < 0) throw new Error("negative input: " + n); return Math.sqrt(n); }
var dump = null;
try { risky(-4); } catch (e) {
  dump = { system: "SigDump", error: e.message, stack: e.stack.split("\n").slice(0, 3).join(" <- "), time: new Date().toISOString() };
}
console.log("System: " + dump.system + " | Captures: all faults");
console.log("Dump: " + JSON.stringify(dump));
console.log("Pipeline: SigCrash analyzer -> filed");

